{
  "a_sentences": [
    {
      "a_text": "Le maître de l'ouvrage a opté pour la garantie des défauts après la livraison de l'ouvrage.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Après la livraison, le maître doit vérifier l'ouvrage aussitôt qu'il le peut et signaler les défauts à l'entrepreneur.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "L'entrepreneur est libéré de toute responsabilité pour les défauts dénoncés tardivement et les droits du maître se périment.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le maître doit exprimer la volonté de ne pas reconnaître l'ouvrage comme conforme et de mettre en cause la responsabilité de l'entrepreneur.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "L'entrepreneur doit comprendre quels points sont contestés, la nature, l'emplacement et l'étendue du défaut afin de le constater.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "L'entrepreneur supporte le fardeau de l'allégation objectif de l'absence d'avis des défauts ou de sa tardiveté, tandis que le maître supporte le fardeau de la preuve de l'avis, de son contenu et du moment de la connaissance du défaut.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que le maître de l'ouvrage n'était pas au bénéfice de la garantie pour les défauts.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Faute d'avis des défauts, les conditions du droit à la garantie contre les défauts ne sont pas réunies.",
      "b_propositions": ["P8"]
    }
  ]
}
